package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.*;import org.junit.jupiter.api.Test;import dao.OrdenPagoDAO;import negocio.*;
class ConsultaOrdenPagoClienteServiceTest {@Test void contratoManualEsHonesto(){OrdenPagoDAO dao=mock(OrdenPagoDAO.class);Clock c=Clock.fixed(Instant.parse("2026-10-14T07:00:00Z"),ZoneOffset.UTC);ConsultaOrdenPagoClienteService s=new ConsultaOrdenPagoClienteService(dao,c);OrdenPago o=new OrdenPago();o.setId(4);o.setReservaId(8);o.setImporte(new BigDecimal("6250.00"));o.setEstado(EstadoOrdenPago.ESPERANDO_VERIFICACION);o.setFechaExpiracion(LocalDateTime.of(2026,10,14,7,10));var dto=s.convertir(o);assertTrue(dto.puedeInformarTransferencia());assertFalse(dto.puedePagarOnline());assertEquals(600,dto.segundosRestantes());assertTrue(dto.mensaje().contains("administración"));}}
